// ---------------------------------------------------------------------------
// 2. WEAPON & CLASS KINEMATICS CONFIGURATION
// ---------------------------------------------------------------------------
const RGX_UNARMED = /^hands$|^unarmed$|^none$|^bare_hands$|^maos$/i;
const RGX_STAFF = /staff|wand|scepter|rod|cajado|varinha/i;
const RGX_HAMMER = /hammer|club|mace|pickaxe|maul/i;
const RGX_SPEAR = /spear|lance|halberd|trident|pike/i;
const RGX_DAGGER = /dagger|faca|stiletto|kris|dirk|misericorde/i;
const RGX_SWORD = /sword|greatsword|broadsword|scrapsword|claymore|zweihander|flamberge|scimitar|saber|rapier|katana|estoc|falchion|spada|espada|runeblade|wyrmblade|(?:^|[\s_-])blade(?:[\s_-]|$)/i;
const RGX_AXE = /axe|cleaver|hatchet/i;
const RGX_BOW = /(?:^|[\s_-])(?:short|long|great|composite)?bow(?:[\s_-]|$)|crossbow|\barrows?\b|flecha|\barco\b|arbalest|quiver|archery|rainbow_bow/i;

export function getWeaponCategory(equippedWeapon, playerClass = "") {
  if (!equippedWeapon || typeof equippedWeapon !== "string") {
    if (playerClass === "ranger") return "bow";
    return "unarmed";
  }
  if (RGX_UNARMED.test(equippedWeapon)) return "unarmed";
  if (RGX_STAFF.test(equippedWeapon)) return "staff";
  if (RGX_HAMMER.test(equippedWeapon)) return "hammer";
  if (RGX_SPEAR.test(equippedWeapon)) return "spear";
  if (RGX_DAGGER.test(equippedWeapon) && !RGX_SWORD.test(equippedWeapon)) return "dagger";
  if (RGX_AXE.test(equippedWeapon)) return "axe";
  if (RGX_SWORD.test(equippedWeapon)) return "sword";
  if (RGX_BOW.test(equippedWeapon) && !RGX_STAFF.test(equippedWeapon)) return "bow";
  return "sword";
}

export function isTwoHandedWeapon(equippedWeapon, playerClass = "") {
  if (!equippedWeapon || typeof equippedWeapon !== "string") return false;
  if (RGX_STAFF.test(equippedWeapon)) return false;
  const rgx2H = /(?:^|[\s_-])(?:short|long|great|composite)?bow(?:[\s_-]|$)|rainbow_bow|crossbow|arrow|spear|lance|halberd|trident|pike|hammer|maul|axe|greatsword|claymore|zweihander|2h/i;
  if (rgx2H.test(equippedWeapon)) return true;
  if (playerClass === "warrior" && !RGX_DAGGER.test(equippedWeapon)) return true;
  return false;
}

export function getPlayerAttackDuration(playerClass, equippedWeapon, customBonuses = null) {
  const cat = getWeaponCategory(equippedWeapon, playerClass);
  let baseMs = 450;
  if (cat === "bow") baseMs = 800;
  else if (playerClass === "warrior") baseMs = 800;
  else if (playerClass === "ranger") baseMs = 800;
  else if (playerClass === "healer") baseMs = 750;
  else if (playerClass === "mechanist") baseMs = 750;
  else if (playerClass === "hemomancer") baseMs = 700;
  else if (playerClass === "assassin") baseMs = 450;
  else if (playerClass === "mage" || playerClass === "pyromancer" || playerClass === "bard") baseMs = 450;

  if (customBonuses && typeof customBonuses === "object") {
    const atkSpeedModifier = Math.max(0.2, 1 - (customBonuses.attackSpeedBonus || 0) - ((customBonuses.dexterity || 0) * 0.01));
    baseMs = Math.max(80, Math.round(baseMs * atkSpeedModifier));
  }
  return baseMs;
}

export function getDefaultWeaponWristAngle(category, equippedWeapon = "") {
  const wep = typeof equippedWeapon === "string" ? equippedWeapon.toLowerCase() : "";
  if (wep.includes("cleaver") || category === "cleaver") return 1.05;
  if (category === "bow") return Math.PI / 2;
  if (category === "spear") return 0.20;
  if (category === "axe") return 0.45;
  if (category === "hammer") return 0.60;
  if (category === "staff") return 0.02;
  if (category === "dagger") return Math.PI / 2.2;
  return Math.PI / 3;
}

// ---------------------------------------------------------------------------
// 3. ATTACK KINEMATICS ENGINE (COMBO ARCS, LUNGES, TORSO TILTS)
// ---------------------------------------------------------------------------
export function getAttackKinematics(category, attackPhase, comboStep = 0, opts = {}) {
  const is2H = !!opts.isTwoHanded;
  const isWindup = !!opts.isWindup;
  const eqWep = (typeof opts.equippedWeapon === "string" ? opts.equippedWeapon : "") || (typeof opts === "string" ? opts : "");

  let swingOffset = 0;
  let torsoTilt = 0;
  let lungeX = 0;
  let lungeY = 0;
  let wristAngle = getDefaultWeaponWristAngle(category, eqWep);
  let progress = 0;
  let stanceFlex = 0;
  let headPitch = 0;

  if (isWindup) {
    const windT = Math.min(1.0, attackPhase / 0.8);
    const easeWind = windT * windT;
    swingOffset = -0.75 * easeWind;
    torsoTilt = -0.16 * easeWind;
    lungeX = -2.5 * easeWind;
    lungeY = -2.5 * easeWind;
    wristAngle = getDefaultWeaponWristAngle(category, eqWep) - 0.45 * easeWind;
    progress = -0.2 * easeWind;
    stanceFlex = -0.2 * easeWind;
    headPitch = 0.05 * easeWind;
    return { swingOffset, torsoTilt, lungeX, lungeY, wristAngle, progress, stanceFlex, headPitch };
  }

  if (category === "bow") {
    wristAngle = Math.PI / 2;
    if (attackPhase < 0.38) {
      const t = attackPhase / 0.38;
      const easeDraw = t * t * (3 - 2 * t);
      torsoTilt = -0.06 * easeDraw;
      lungeX = -2.5 * easeDraw;
      lungeY = -2.5 * easeDraw;
      progress = 0.6 * easeDraw;
      stanceFlex = 0.3 * easeDraw;
      headPitch = -0.02 * easeDraw;
    } else if (attackPhase < 0.58) {
      const t = (attackPhase - 0.38) / 0.20;
      const kick = Math.sin(t * Math.PI);
      torsoTilt = 0.04 * (1 - t);
      lungeX = -(2.5 - kick * 1.8);
      lungeY = -(2.5 - kick * 1.8);
      wristAngle = Math.PI / 2 - kick * 0.16;
      progress = 1.0;
      stanceFlex = 0.35 + kick * 0.15;
      headPitch = 0.04 * kick;
    } else {
      const t = (attackPhase - 0.58) / 0.42;
      const easeRec = (1 - t) * (1 - t);
      lungeX = -1.0 * easeRec;
      lungeY = -1.0 * easeRec;
      progress = 1.0 * easeRec;
      stanceFlex = 0.3 * easeRec;
    }
  } else if (category === "dagger") {
    if (attackPhase < 0.20) {
      const t = attackPhase / 0.20;
      const easeWind = t * t * (3 - 2 * t);
      swingOffset = -0.60 * easeWind;
      torsoTilt = -0.18 * easeWind;
      lungeX = -1.5 * easeWind;
      lungeY = -1.5 * easeWind;
      wristAngle = Math.PI / 2.2 - 0.5 * easeWind;
      progress = -0.2 * easeWind;
    } else if (attackPhase < 0.48) {
      const t = (attackPhase - 0.20) / 0.28;
      const easeHit = t * t * (3 - 2 * t);
      swingOffset = -0.60 + easeHit * 2.40;
      torsoTilt = -0.18 + easeHit * 0.40;
      lungeX = -1.5 + easeHit * 13.5;
      lungeY = -1.5 + easeHit * 13.5;
      wristAngle = (Math.PI / 2.2 - 0.5) + easeHit * 1.65;
      progress = easeHit * 1.15;
      stanceFlex = 0.55 * easeHit;
      headPitch = 0.12 * easeHit;
    } else if (attackPhase < 0.58) {
      swingOffset = 1.80;
      torsoTilt = 0.22;
      lungeX = 12;
      lungeY = 12;
      wristAngle = Math.PI / 2.2 + 1.15;
      progress = 1.15;
      stanceFlex = 0.55;
    } else {
      const t = (attackPhase - 0.58) / 0.42;
      const easeRec = (1 - t) * (1 - t);
      swingOffset = 1.80 * easeRec;
      torsoTilt = 0.22 * easeRec;
      lungeX = 12 * easeRec;
      lungeY = 12 * easeRec;
      wristAngle = Math.PI / 2.2 + 1.15 * easeRec;
      progress = 1.15 * easeRec;
      stanceFlex = 0.55 * easeRec;
    }
  } else if (category === "staff") {
    const baseStaffWrist = 0.02;
    if (attackPhase < 0.25) {
      const t = attackPhase / 0.25;
      const easeWind = t * t * (3 - 2 * t);
      swingOffset = -0.85 * easeWind;
      torsoTilt = -0.05 * easeWind;
      lungeX = -1.0 * easeWind;
      lungeY = -0.8 * easeWind;
      wristAngle = baseStaffWrist - 0.20 * easeWind;
      progress = -0.10 * easeWind;
    } else if (attackPhase < 0.52) {
      const t = (attackPhase - 0.25) / 0.27;
      const easeHit = t * t * (3 - 2 * t);
      swingOffset = -0.85 + easeHit * 1.85;
      torsoTilt = -0.05 + easeHit * 0.14;
      lungeX = -1.0 + easeHit * 8.0;
      lungeY = -0.8 + easeHit * 8.0;
      wristAngle = (baseStaffWrist - 0.20) + easeHit * 0.55;
      progress = easeHit * 1.05;
      stanceFlex = 0.35 * easeHit;
    } else if (attackPhase < 0.64) {
      swingOffset = 1.0;
      torsoTilt = 0.09;
      lungeX = 7;
      lungeY = 7;
      wristAngle = baseStaffWrist + 0.35;
      progress = 1.05;
      stanceFlex = 0.35;
    } else {
      const t = (attackPhase - 0.64) / 0.36;
      const easeRec = (1 - t) * (1 - t);
      swingOffset = 1.0 * easeRec;
      torsoTilt = 0.09 * easeRec;
      lungeX = 7 * easeRec;
      lungeY = 7 * easeRec;
      wristAngle = baseStaffWrist + 0.35 * easeRec;
      progress = 1.05 * easeRec;
      stanceFlex = 0.35 * easeRec;
    }
  } else {
    // Swords, Greatswords, Axes, Polearms: 3-Hit Combo Arc System
    const maxLunge = is2H ? 16 : 11;
    if (comboStep === 1) {
      // Step 1: Low-to-High Horizontal Reverse Sweep
      if (attackPhase < 0.22) {
        const t = attackPhase / 0.22;
        const easeWind = t * t * (3 - 2 * t);
        swingOffset = 1.25 * easeWind;
        torsoTilt = 0.16 * easeWind;
        lungeX = -2.0 * easeWind;
        lungeY = -2.0 * easeWind;
        wristAngle = Math.PI / 3 + 0.45 * easeWind;
      } else if (attackPhase < 0.50) {
        const t = (attackPhase - 0.22) / 0.28;
        const easeHit = t * t * (3 - 2 * t);
        swingOffset = 1.25 - easeHit * 3.45;
        torsoTilt = 0.16 - easeHit * 0.38;
        lungeX = -2.0 + easeHit * (maxLunge + 2.0);
        lungeY = -2.0 + easeHit * (maxLunge + 2.0);
        wristAngle = (Math.PI / 3 + 0.45) - easeHit * 1.55;
        progress = easeHit * 1.20;
        stanceFlex = 0.65 * easeHit;
        headPitch = 0.12 * easeHit;
      } else if (attackPhase < 0.62) {
        swingOffset = -2.20;
        torsoTilt = -0.22;
        lungeX = maxLunge;
        lungeY = maxLunge;
        wristAngle = Math.PI / 3 - 1.10;
        progress = 1.20;
        stanceFlex = 0.65;
      } else {
        const t = (attackPhase - 0.62) / 0.38;
        const easeRec = (1 - t) * (1 - t);
        swingOffset = -2.20 * easeRec;
        torsoTilt = -0.22 * easeRec;
        lungeX = maxLunge * easeRec;
        lungeY = maxLunge * easeRec;
        wristAngle = (Math.PI / 3) - 1.10 * easeRec;
        progress = 1.20 * easeRec;
        stanceFlex = 0.65 * easeRec;
      }
    } else if (comboStep === 2) {
      // Step 2: Ground-Shattering Overhead Execution Slam
      const heavyLunge = is2H ? 19 : 13;
      if (attackPhase < 0.26) {
        const t = attackPhase / 0.26;
        const easeWind = t * t * (3 - 2 * t);
        swingOffset = -1.70 * easeWind;
        torsoTilt = -0.24 * easeWind;
        lungeX = -3.5 * easeWind;
        lungeY = -3.5 * easeWind;
        wristAngle = Math.PI / 3 - 0.90 * easeWind;
      } else if (attackPhase < 0.54) {
        const t = (attackPhase - 0.26) / 0.28;
        const easeHit = t * t * (3 - 2 * t);
        swingOffset = -1.70 + easeHit * 3.75;
        torsoTilt = -0.24 + easeHit * 0.52;
        lungeX = -3.5 + easeHit * (heavyLunge + 3.5);
        lungeY = -3.5 + easeHit * (heavyLunge + 3.5);
        wristAngle = (Math.PI / 3 - 0.90) + easeHit * 2.10;
        progress = easeHit * 1.30;
        stanceFlex = 0.85 * easeHit;
        headPitch = 0.18 * easeHit;
      } else if (attackPhase < 0.66) {
        swingOffset = 2.05;
        torsoTilt = 0.28;
        lungeX = heavyLunge;
        lungeY = heavyLunge;
        wristAngle = Math.PI / 3 + 1.20;
        progress = 1.30;
        stanceFlex = 0.85;
      } else {
        const t = (attackPhase - 0.66) / 0.34;
        const easeRec = (1 - t) * (1 - t);
        swingOffset = 2.05 * easeRec;
        torsoTilt = 0.28 * easeRec;
        lungeX = heavyLunge * easeRec;
        lungeY = heavyLunge * easeRec;
        wristAngle = Math.PI / 3 + 1.20 * easeRec;
        progress = 1.30 * easeRec;
        stanceFlex = 0.85 * easeRec;
      }
    } else {
      // Step 0: Heavy Diagonal Cleaving Slash (220-degree arc)
      if (attackPhase < 0.24) {
        const t = attackPhase / 0.24;
        const easeWind = t * t * (3 - 2 * t);
        swingOffset = -1.35 * easeWind;
        torsoTilt = -0.18 * easeWind;
        lungeX = -2.5 * easeWind;
        lungeY = -2.5 * easeWind;
        wristAngle = Math.PI / 3 - 0.45 * easeWind;
      } else if (attackPhase < 0.52) {
        const t = (attackPhase - 0.24) / 0.28;
        const easeHit = t * t * (3 - 2 * t);
        swingOffset = -1.35 + easeHit * 3.25;
        torsoTilt = -0.18 + easeHit * 0.42;
        lungeX = -2.5 + easeHit * (maxLunge + 2.5);
        lungeY = -2.5 + easeHit * (maxLunge + 2.5);
        wristAngle = (Math.PI / 3 - 0.45) + easeHit * 1.55;
        progress = easeHit * 1.20;
        stanceFlex = 0.70 * easeHit;
        headPitch = 0.14 * easeHit;
      } else if (attackPhase < 0.64) {
        swingOffset = 1.90;
        torsoTilt = 0.24;
        lungeX = maxLunge;
        lungeY = maxLunge;
        wristAngle = Math.PI / 3 + 1.10;
        progress = 1.20;
        stanceFlex = 0.70;
      } else {
        const t = (attackPhase - 0.64) / 0.36;
        const easeRec = (1 - t) * (1 - t);
        swingOffset = 1.90 * easeRec;
        torsoTilt = 0.24 * easeRec;
        lungeX = maxLunge * easeRec;
        lungeY = maxLunge * easeRec;
        wristAngle = Math.PI / 3 + 1.10 * easeRec;
        progress = 1.20 * easeRec;
        stanceFlex = 0.70 * easeRec;
      }
    }
  }

  return { swingOffset, torsoTilt, lungeX, lungeY, wristAngle, progress, stanceFlex, headPitch };
}

// ---------------------------------------------------------------------------
// PALETTE & APPEARANCE RESOLVERS FOR STUDIO-GRADE PROCEDURAL RENDERING
// ---------------------------------------------------------------------------
const SKIN_PALETTES = {
  fair: { base: "#f6d5ba", shade: "#d9ad8b", hi: "#ffead8" },
  pale: { base: "#f7e3d4", shade: "#d8beab", hi: "#fff3ea" },
  porcelain: { base: "#faece2", shade: "#dfc7b8", hi: "#fff8f2" },
  peach: { base: "#f4cbb2", shade: "#d49f82", hi: "#ffe4d2" },
  tan: { base: "#d69e72", shade: "#ad7449", hi: "#eab992" },
  warm_amber: { base: "#cf9263", shade: "#9e663b", hi: "#e6af84" },
  bronze: { base: "#b87a4b", shade: "#8a532b", hi: "#d2986b" },
  espresso: { base: "#704832", shade: "#4d2e1d", hi: "#8f6147" },
  elf: { base: "#efe0d8", shade: "#cbb3a6", hi: "#fff5ef" },
  frost: { base: "#cbe3f5", shade: "#94b8d6", hi: "#e8f4fc" },
  frost_ogre: { base: "#7fb3d5", shade: "#4a7fa3", hi: "#a9d1eb" },
  orc: { base: "#6fa352", shade: "#4b7534", hi: "#8ec270" }
};

function drawStarGlint(ctx, x, y, r, color = "#ffffff", glowColor = "rgba(255,255,255,0.45)", pulse = 1) {
  ctx.save();
  ctx.translate(x, y);
  const rad = r * pulse;
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, rad * 0.95);
  g.addColorStop(0, "rgba(255,255,255,0.95)");
  g.addColorStop(0.28, glowColor);
  g.addColorStop(1, "rgba(255,255,255,0)");
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, 0, rad * 0.95, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = color;
  ctx.beginPath();
  const s = rad * 0.038;
  ctx.moveTo(0, -rad * 1.15);
  ctx.quadraticCurveTo(s, -s, rad * 1.15, 0);
  ctx.quadraticCurveTo(s, s, 0, rad * 1.15);
  ctx.quadraticCurveTo(-s, s, -rad * 1.15, 0);
  ctx.quadraticCurveTo(-s, -s, 0, -rad * 1.15);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

// ---------------------------------------------------------------------------
// 4. ANIMATED CHARACTER CONTROLLER CLASS
// ---------------------------------------------------------------------------
export class CharacterController {
  constructor(initialPreset = null) {
    this.preset = initialPreset || CHARACTER_PRESETS[0] || {};
    this.playerClass = this.preset.classHint || this.preset.playerClass || "warrior";
    this.weapon = this.preset.weapon || "iron_greatsword";
    this.armor = this.preset.armor || "iron_plate";
    this.helmet = this.preset.helmet || null;
    this.shield = this.preset.shield || null;
    this.bodyColor = this.preset.bodyColor || "#38bdf8";

    // Orientation & Locomotion
    this.facingAngle = Math.PI / 2; // 90 deg = Facing front
    this.moving = false;
    this.speedFactor = 1.0;
    this.walkPhase = 0;
    this.lastStepIndex = 0;
    this.stepTriggered = false;

    // Combat & Attack Combo State Machine
    this.isAttacking = false;
    this.attackStartTime = 0;
    this.attackDuration = 450;
    this.comboStep = 0;
    this.lastAttackTime = 0;
    this.attackPhase = 0;
    this.attackKinematics = { swingOffset: 0, torsoTilt: 0, lungeX: 0, lungeY: 0, wristAngle: 0, progress: 0, stanceFlex: 0, headPitch: 0 };

    // Dodge Roll Evasion
    this.isRolling = false;
    this.rollStartTime = 0;
    this.rollDuration = 400;
    this.rollProgress = 0;
    this.rollDirX = 0;
    this.rollDirY = 1;

    this.lastUpdateTime = performance.now();
  }

  /**
   * Switches to another preset configuration by ID or object.
   */
  setPreset(presetOrId) {
    let target = null;
    if (typeof presetOrId === "string") {
      target = CHARACTER_PRESETS.find(p => p.id === presetOrId);
    } else if (presetOrId && typeof presetOrId === "object") {
      target = presetOrId;
    }
    if (!target) return false;

    this.preset = target;
    this.playerClass = target.classHint || target.playerClass || this.playerClass;
    this.weapon = target.weapon || this.weapon;
    this.armor = target.armor || this.armor;
    this.helmet = target.helmet !== undefined ? target.helmet : null;
    this.shield = target.shield !== undefined ? target.shield : null;
    if (target.bodyColor) this.bodyColor = target.bodyColor;
    return true;
  }

  /**
   * Sets locomotion walking state.
   */
  setMoving(isMoving) {
    this.moving = !!isMoving;
  }

  /**
   * Sets character facing angle in radians (0 = right, PI/2 = down/front, PI = left, 3PI/2 = up/back).
   */
  setFacingAngle(radians) {
    this.facingAngle = ((radians % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2);
  }

  /**
   * Triggers the weapon attack combo.
   */
  triggerAttack() {
    const now = performance.now();
    this.attackDuration = getPlayerAttackDuration(this.playerClass, this.weapon);

    // Combo window calculation (chain combo within 1200ms)
    if (now - this.lastAttackTime < 1200 && now - this.lastAttackTime > 150) {
      this.comboStep = (this.comboStep + 1) % 3;
    } else {
      this.comboStep = 0;
    }

    this.lastAttackTime = now;
    this.attackStartTime = now;
    this.isAttacking = true;
    return this.comboStep;
  }

  /**
   * Triggers a dodge roll or tactical dash.
   */
  triggerRoll(dirX = null, dirY = null) {
    const now = performance.now();
    this.rollStartTime = now;
    this.rollDuration = 400;
    this.isRolling = true;
    this.rollProgress = 0;
    this.rollDirX = dirX !== null ? dirX : Math.cos(this.facingAngle);
    this.rollDirY = dirY !== null ? dirY : Math.sin(this.facingAngle);
  }

  /**
   * Per-frame animation and kinematics update.
   * @param {number} [customDt] Optional delta time in seconds. If omitted, computes from clock.
   */
  update(customDt = null) {
    const now = performance.now();
    let dt = customDt;
    if (dt === null || typeof dt !== "number") {
      dt = (now - this.lastUpdateTime) / 1000;
      if (dt < 0 || dt > 0.1 || isNaN(dt)) dt = 0.016;
    }
    this.lastUpdateTime = now;

    // 1. Walking Animation Kinematics
    this.stepTriggered = false;
    if (this.moving) {
      this.walkPhase += dt * 11.5 * this.speedFactor;
      const currentStep = Math.floor((this.walkPhase + Math.PI / 2) / Math.PI);
      if (currentStep > this.lastStepIndex) {
        this.stepTriggered = true;
        this.lastStepIndex = currentStep;
      }
    } else {
      this.walkPhase *= 0.82;
      if (Math.abs(this.walkPhase) < 0.005) this.walkPhase = 0;
    }

    // 2. Attack Combo Simulation
    if (this.isAttacking) {
      const elapsed = now - this.attackStartTime;
      if (elapsed < this.attackDuration) {
        this.attackPhase = Math.max(0, Math.min(1.0, elapsed / this.attackDuration));
        const cat = getWeaponCategory(this.weapon, this.playerClass);
        const is2H = isTwoHandedWeapon(this.weapon, this.playerClass);
        const isCaster = false; // Full staff/weapon arc animation
        this.attackKinematics = getAttackKinematics(cat, this.attackPhase, this.comboStep, {
          isTwoHanded: is2H,
          isWindup: isCaster,
          equippedWeapon: this.weapon
        });
      } else {
        this.isAttacking = false;
        this.attackPhase = 1.0;
        this.attackKinematics = { swingOffset: 0, torsoTilt: 0, lungeX: 0, lungeY: 0, wristAngle: 0, progress: 0, stanceFlex: 0, headPitch: 0 };
      }
    }

    // 3. Dodge Roll Simulation
    if (this.isRolling) {
      const rollElapsed = now - this.rollStartTime;
      if (rollElapsed < this.rollDuration) {
        this.rollProgress = Math.max(0, Math.min(1.0, rollElapsed / this.rollDuration));
      } else {
        this.isRolling = false;
        this.rollProgress = 1.0;
      }
    }
  }

  /**
   * Renders the animated character to any HTML5 Canvas 2D context.
   * Uses high-detail procedural vector rendering faithful to the game's faceted models.
   */
  draw(ctx, x, y, scale = 2.0) {
    if (typeof window !== "undefined" && typeof window.drawPlayerCharacter === "function") {
      return window.drawPlayerCharacter(ctx, x, y, this, scale);
    }

    const now = typeof performance !== "undefined" ? performance.now() : Date.now();
    const s = scale / 2;
    ctx.save();
    ctx.translate(x, y);

    const deg = (((this.facingAngle * 180) / Math.PI) % 360 + 360) % 360;
    const isFlip = deg > 135 && deg < 225;
    if (isFlip) ctx.scale(-1, 1);

    // Dynamic Kinematics Transformations
    const kin = this.attackKinematics;
    const lungeDirX = Math.cos(this.facingAngle) * (isFlip ? -1 : 1);
    const lungeDirY = Math.sin(this.facingAngle);
    const effLungeX = kin.lungeX * lungeDirX * s * 0.45;
    const effLungeY = kin.lungeY * lungeDirY * s * 0.45;

    const rollOffsetX = this.isRolling ? Math.sin(this.rollProgress * Math.PI) * 18 * s * this.rollDirX : 0;
    const rollRot = this.isRolling ? this.rollProgress * Math.PI * 2 : 0;

    ctx.translate(effLungeX + rollOffsetX, effLungeY);
    if (this.isRolling) ctx.rotate(rollRot);

    // Subtle idle breathing + walking bob
    const breathe = Math.sin(now * 0.0032) * 1.1 * s;
    const legSwing = Math.sin(this.walkPhase) * 0.42;
    const armSwing = Math.sin(this.walkPhase) * 0.32;
    const walkBobY = Math.abs(Math.sin(this.walkPhase)) * 2.4 * s;
    const torsoTiltAngle = kin.torsoTilt * 0.65 + (this.moving ? 0.05 : 0);

    // Determine archetype theme from preset / armor / weapon
    const armor = (this.armor || "").toLowerCase();
    const weapon = (this.weapon || "").toLowerCase();
    const helmet = (this.helmet || "").toLowerCase();
    const cls = (this.playerClass || "").toLowerCase();
    const skinKey = (this.preset && (this.preset.skinTone || (this.preset.appearance && this.preset.appearance.skinTone))) || "fair";
    const skin = SKIN_PALETTES[skinKey] || SKIN_PALETTES.fair;

    const isPyroOrHemo = cls === "pyromancer" || cls === "hemomancer" || armor.includes("pyromancer") || weapon.includes("inferno") || weapon.includes("hemomancer");
    const isMage = !isPyroOrHemo && (cls === "mage" || cls === "healer" || armor.includes("mage") || armor.includes("healer") || weapon.includes("staff"));
    const isRanger = cls === "ranger" || cls === "assassin" || cls === "bard" || weapon.includes("bow") || weapon.includes("dagger");
    const isDragonTheme = armor.includes("dragon") || weapon.includes("dragon");
    const isFrostTheme = armor.includes("frost") || weapon.includes("frost");
    const isWolfTheme = armor.includes("wolf") || weapon.includes("wolf");
    const isSlimeTheme = armor.includes("slime") || weapon.includes("slime");

    // 1. Ground Drop Shadow + Subtle Pedestal Ring
    const shadowGrad = ctx.createRadialGradient(2 * s, 29 * s, 2 * s, 0, 29 * s, 24 * s);
    shadowGrad.addColorStop(0, "rgba(4, 8, 18, 0.62)");
    shadowGrad.addColorStop(0.65, "rgba(4, 8, 18, 0.28)");
    shadowGrad.addColorStop(1, "rgba(4, 8, 18, 0)");
    ctx.fillStyle = shadowGrad;
    ctx.beginPath();
    ctx.ellipse(2 * s, 29 * s, 24 * s, 7.5 * s, 0, 0, Math.PI * 2);
    ctx.fill();

    // 2. Legs & Greaves (Blocky Faceted Game Style)
    const drawLeg = (sideSign, swing) => {
      ctx.save();
      ctx.translate(sideSign * 5.6 * s, 9 * s - walkBobY * 0.5);
      ctx.rotate(swing);

      if (isPyroOrHemo) {
        // Dark obsidian & gold-studded greaves with glowing orange knee/foot orbs
        ctx.fillStyle = "#180d08";
        ctx.fillRect(-4.6 * s, 0, 9.2 * s, 17 * s);
        ctx.strokeStyle = "#d97706";
        ctx.lineWidth = 0.9 * s;
        ctx.strokeRect(-4.4 * s, 0.5 * s, 8.8 * s, 16 * s);
        // Gold vertical pixel-studs
        ctx.fillStyle = "#f59e0b";
        for (let r = 0; r < 3; r++) {
          ctx.fillRect(-2.6 * s, (3 + r * 4) * s, 1.8 * s, 2.2 * s);
          ctx.fillRect(0.8 * s, (3 + r * 4) * s, 1.8 * s, 2.2 * s);
        }
        // Glowing orange orb at boot tip
        const bootOrb = ctx.createRadialGradient(0, 17.5 * s, 0.5 * s, 0, 17.5 * s, 4 * s);
        bootOrb.addColorStop(0, "#fef08a");
        bootOrb.addColorStop(0.5, "#f97316");
        bootOrb.addColorStop(1, "#9a3412");
        ctx.fillStyle = bootOrb;
        ctx.beginPath();
        ctx.arc(0, 17.5 * s, 3.6 * s, 0, Math.PI * 2);
        ctx.fill();
      } else if (isMage) {
        // Arcane navy-indigo boots with gold trim and cyan crystal accents
        ctx.fillStyle = "#171c3a";
        ctx.fillRect(-4.6 * s, 0, 9.2 * s, 16.5 * s);
        ctx.fillStyle = "#252e5e";
        ctx.fillRect(-3.6 * s, 1 * s, 4 * s, 13 * s);
        // Cyan rune diagonal
        ctx.strokeStyle = "#38bdf8";
        ctx.lineWidth = 1.4 * s;
        ctx.beginPath();
        ctx.moveTo(-3.5 * s, 6 * s);
        ctx.lineTo(3.5 * s, 10 * s);
        ctx.stroke();
        // Gold toe cap
        ctx.fillStyle = "#d4a44a";
        ctx.fillRect(-4.6 * s, 14.5 * s, 9.2 * s, 3.2 * s);
      } else if (isRanger) {
        // Dark brown leather boots with gold buckle
        ctx.fillStyle = "#3b2110";
        ctx.fillRect(-4.6 * s, 0, 9.2 * s, 16 * s);
        ctx.fillStyle = "#5c3419";
        ctx.fillRect(-4.8 * s, 3 * s, 9.6 * s, 6 * s);
        // Gold buckle
        ctx.fillStyle = "#f59e0b";
        ctx.fillRect(-2 * s, 6.5 * s, 4 * s, 3.2 * s);
        ctx.fillStyle = "#291509";
        ctx.fillRect(-0.8 * s, 7.3 * s, 1.6 * s, 1.6 * s);
        // Rounded leather boot foot
        ctx.fillStyle = "#472813";
        ctx.beginPath();
        ctx.ellipse(0, 16.8 * s, 5.6 * s, 3.2 * s, 0, 0, Math.PI * 2);
        ctx.fill();
      } else {
        // Faceted silver/steel plate greaves & sabatons
        const plateHi = isDragonTheme ? "#fca5a5" : isFrostTheme ? "#e0f2fe" : "#f1f5f9";
        const plateMid = isDragonTheme ? "#b91c1c" : isFrostTheme ? "#7dd3fc" : "#cbd5e1";
        const plateDark = isDragonTheme ? "#450a0a" : isFrostTheme ? "#0369a1" : "#64748b";
        ctx.fillStyle = plateDark;
        ctx.fillRect(-5 * s, 0, 10 * s, 16.5 * s);
        ctx.fillStyle = plateMid;
        ctx.fillRect(-4 * s, 0.5 * s, 6 * s, 15.5 * s);
        ctx.fillStyle = plateHi;
        ctx.fillRect(-2.5 * s, 1 * s, 2.5 * s, 14.5 * s);
        // Knee & shin horizontal joint lines
        ctx.fillStyle = "#1e293b";
        ctx.fillRect(-4.8 * s, 5.5 * s, 9.6 * s, 1.3 * s);
        ctx.fillRect(-4.8 * s, 11 * s, 9.6 * s, 1.2 * s);
        // Wide faceted sabaton foot
        ctx.fillStyle = plateMid;
        ctx.beginPath();
        ctx.roundRect(-6.2 * s, 15 * s, 12.4 * s, 4.5 * s, 2 * s);
        ctx.fill();
        ctx.fillStyle = plateHi;
        ctx.fillRect(-5 * s, 15.6 * s, 8 * s, 1.8 * s);
      }
      ctx.restore();
    };

    drawLeg(-1, legSwing);
    drawLeg(1, -legSwing);

    // 3. Torso, Pauldrons & Head
    ctx.save();
    ctx.translate(0, -4 * s - walkBobY + breathe * 0.5);
    ctx.rotate(torsoTiltAngle);

    if (isPyroOrHemo) {
      // Dark robe torso with gold belts, crimson sash & diagonal bandolier
      ctx.fillStyle = "#1c0e09";
      ctx.beginPath();
      ctx.roundRect(-11.5 * s, -12 * s, 23 * s, 23 * s, 3 * s);
      ctx.fill();

      // Crimson chest cloth & sash
      ctx.fillStyle = "#b91c1c";
      ctx.beginPath();
      ctx.moveTo(0, -10 * s);
      ctx.lineTo(8 * s, -7 * s);
      ctx.lineTo(5 * s, 2 * s);
      ctx.lineTo(-2 * s, -2 * s);
      ctx.closePath();
      ctx.fill();

      // Gold belt & trim lines
      ctx.fillStyle = "#f59e0b";
      ctx.fillRect(-11 * s, 3.5 * s, 22 * s, 1.5 * s);
      ctx.fillRect(-11 * s, 7.5 * s, 22 * s, 1.5 * s);
      ctx.fillStyle = "#fef08a";
      ctx.fillRect(-2.5 * s, 4.2 * s, 5 * s, 4 * s);
      ctx.fillStyle = "#1e293b";
      ctx.fillRect(-1 * s, 5 * s, 2 * s, 2.4 * s);
      // Crimson belt ribbon hanging left
      ctx.fillStyle = "#dc2626";
      ctx.fillRect(-6.5 * s, 7 * s, 4 * s, 7 * s);

      // Diagonal bandolier with glowing orange gem
      ctx.strokeStyle = "#d97706";
      ctx.lineWidth = 2 * s;
      ctx.beginPath();
      ctx.moveTo(-9 * s, -10 * s);
      ctx.lineTo(8 * s, 3 * s);
      ctx.stroke();
      const chestGem = ctx.createRadialGradient(-0.5 * s, -3.5 * s, 0.5 * s, -0.5 * s, -3.5 * s, 3.8 * s);
      chestGem.addColorStop(0, "#ffffff");
      chestGem.addColorStop(0.4, "#fb923c");
      chestGem.addColorStop(1, "#9a3412");
      ctx.fillStyle = chestGem;
      ctx.beginPath();
      ctx.arc(-0.5 * s, -3.5 * s, 3.4 * s, 0, Math.PI * 2);
      ctx.fill();

      // Rounded dark pauldrons with orange gems
      for (const side of [-1, 1]) {
        ctx.save();
        ctx.translate(side * 13 * s, -6 * s);
        ctx.fillStyle = "#24120b";
        ctx.beginPath();
        ctx.arc(0, 0, 6.5 * s, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = "#ea580c";
        ctx.lineWidth = 1.1 * s;
        ctx.stroke();
        ctx.fillStyle = "#fb923c";
        ctx.beginPath();
        ctx.arc(side * -1 * s, -1 * s, 2.1 * s, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }
    } else if (isMage) {
      // Arcane indigo-navy torso with high purple mantle & glowing cyan astrolabe
      ctx.fillStyle = "#171c36";
      ctx.beginPath();
      ctx.roundRect(-11.5 * s, -12 * s, 23 * s, 23 * s, 3.5 * s);
      ctx.fill();

      // Leather & cyan-gem belt
      ctx.fillStyle = "#5c3419";
      ctx.fillRect(-11 * s, 5.5 * s, 22 * s, 4 * s);
      ctx.fillStyle = "#7dd3fc";
      ctx.beginPath();
      ctx.arc(0, 7.5 * s, 3.2 * s, 0, Math.PI * 2);
      ctx.fill();

      // Gold astrolabe chest emblem with cyan core
      ctx.strokeStyle = "#d4a44a";
      ctx.lineWidth = 1.6 * s;
      ctx.beginPath();
      ctx.arc(0, -1.5 * s, 4.8 * s, 0, Math.PI * 2);
      ctx.stroke();
      for (let a = 0; a < 4; a++) {
        const ang = (a * Math.PI) / 2 + Math.PI / 4;
        ctx.beginPath();
        ctx.moveTo(Math.cos(ang) * 4.5 * s, -1.5 * s + Math.sin(ang) * 4.5 * s);
        ctx.lineTo(Math.cos(ang) * 7.5 * s, -1.5 * s + Math.sin(ang) * 7.5 * s);
        ctx.stroke();
      }
      ctx.fillStyle = "#7dd3fc";
      ctx.beginPath();
      ctx.arc(0, -1.5 * s, 2.8 * s, 0, Math.PI * 2);
      ctx.fill();

      // High plush purple mantle collar & shoulder orbs
      const mantleGrad = ctx.createLinearGradient(0, -15 * s, 0, -5 * s);
      mantleGrad.addColorStop(0, "#6d55b5");
      mantleGrad.addColorStop(1, "#3b2d70");
      ctx.fillStyle = mantleGrad;
      ctx.beginPath();
      ctx.ellipse(0, -9.5 * s, 16 * s, 5.8 * s, 0, 0, Math.PI * 2);
      ctx.fill();

      // Cyan shoulder orbs
      for (const side of [-1, 1]) {
        ctx.fillStyle = "#7dd3fc";
        ctx.beginPath();
        ctx.arc(side * 10.5 * s, -9.5 * s, 2.7 * s, 0, Math.PI * 2);
        ctx.fill();
      }
    } else if (isRanger) {
      // Sculpted brown leather cuirass with studded pauldrons & crossed bracers
      const leatherGrad = ctx.createLinearGradient(-11 * s, -12 * s, 11 * s, 10 * s);
      leatherGrad.addColorStop(0, "#7c4722");
      leatherGrad.addColorStop(0.5, "#5c3317");
      leatherGrad.addColorStop(1, "#3b1f0c");
      ctx.fillStyle = leatherGrad;
      ctx.beginPath();
      ctx.roundRect(-11 * s, -12 * s, 22 * s, 22 * s, 4 * s);
      ctx.fill();

      // Warm amber undershirt collar
      ctx.fillStyle = "#d9822b";
      ctx.beginPath();
      ctx.arc(0, -8 * s, 5.5 * s, 0, Math.PI);
      ctx.fill();

      // Round leather pauldrons with gold studs
      for (const side of [-1, 1]) {
        ctx.save();
        ctx.translate(side * 11.5 * s, -7.5 * s);
        const pGrad = ctx.createRadialGradient(-side * 2 * s, -2 * s, 1 * s, 0, 0, 7 * s);
        pGrad.addColorStop(0, "#9a5b2c");
        pGrad.addColorStop(1, "#4a2711");
        ctx.fillStyle = pGrad;
        ctx.beginPath();
        ctx.arc(0, 0, 6.4 * s, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = "#2b1508";
        ctx.lineWidth = 1 * s;
        ctx.stroke();
        ctx.fillStyle = "#fbbf24";
        ctx.beginPath();
        ctx.arc(side * 1.5 * s, -1 * s, 1.3 * s, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }

      // Crossed leather forearm/chest gauntlets folded across chest
      ctx.save();
      ctx.fillStyle = "#8c5127";
      ctx.strokeStyle = "#3b1f0c";
      ctx.lineWidth = 1 * s;
      ctx.beginPath();
      ctx.roundRect(-9 * s, -5 * s, 18 * s, 7 * s, 3 * s);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = "#fbbf24";
      ctx.fillRect(-5 * s, -3 * s, 2.5 * s, 3 * s);
      ctx.fillRect(2.5 * s, -3 * s, 2.5 * s, 3 * s);
      ctx.restore();
    } else {
      // Faceted Knight Plate Cuirass, Angular Pauldrons & Tassets
      const pHi = isDragonTheme ? "#fecaca" : isFrostTheme ? "#ffffff" : "#ffffff";
      const pLight = isDragonTheme ? "#ef4444" : isFrostTheme ? "#bae6fd" : "#e2e8f0";
      const pMid = isDragonTheme ? "#991b1b" : isFrostTheme ? "#38bdf8" : "#94a3b8";
      const pDark = isDragonTheme ? "#450a0a" : isFrostTheme ? "#0369a1" : "#475569";

      // Main breastplate
      ctx.fillStyle = pMid;
      ctx.beginPath();
      ctx.moveTo(-11.5 * s, -12 * s);
      ctx.lineTo(11.5 * s, -12 * s);
      ctx.lineTo(9.5 * s, 6 * s);
      ctx.lineTo(0, 10 * s);
      ctx.lineTo(-9.5 * s, 6 * s);
      ctx.closePath();
      ctx.fill();

      // Left light facet
      ctx.fillStyle = pLight;
      ctx.beginPath();
      ctx.moveTo(-11 * s, -12 * s);
      ctx.lineTo(0, -12 * s);
      ctx.lineTo(0, 9.5 * s);
      ctx.lineTo(-9 * s, 5.5 * s);
      ctx.closePath();
      ctx.fill();

      // Gold Gorget Trim & Center Diamond Emblem
      ctx.strokeStyle = "#f59e0b";
      ctx.lineWidth = 1.6 * s;
      ctx.beginPath();
      ctx.moveTo(-7.5 * s, -11.5 * s);
      ctx.lineTo(0, -7 * s);
      ctx.lineTo(7.5 * s, -11.5 * s);
      ctx.stroke();

      ctx.fillStyle = "#f59e0b";
      ctx.beginPath();
      ctx.moveTo(0, -5.5 * s);
      ctx.lineTo(3.8 * s, -1.5 * s);
      ctx.lineTo(0, 2.5 * s);
      ctx.lineTo(-3.8 * s, -1.5 * s);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = pHi;
      ctx.beginPath();
      ctx.arc(0, -1.5 * s, 1.5 * s, 0, Math.PI * 2);
      ctx.fill();

      // Leather waist belt + segmented plate tassets
      ctx.fillStyle = "#7c2d12";
      ctx.fillRect(-9.5 * s, 5.5 * s, 19 * s, 3 * s);
      for (let t = -2; t <= 2; t++) {
        ctx.fillStyle = t % 2 === 0 ? pLight : pDark;
        ctx.fillRect((t * 3.8 - 1.6) * s, 8 * s, 3.2 * s, 4.5 * s);
      }

      // Winged angular pauldrons
      for (const side of [-1, 1]) {
        ctx.save();
        ctx.translate(side * 13 * s, -7.5 * s);
        ctx.fillStyle = side < 0 ? pLight : pMid;
        ctx.beginPath();
        ctx.moveTo(-side * 3 * s, -6.5 * s);
        ctx.lineTo(side * 5.5 * s, -4 * s);
        ctx.lineTo(side * 6.5 * s, 4.5 * s);
        ctx.lineTo(-side * 2.5 * s, 5.5 * s);
        ctx.closePath();
        ctx.fill();
        ctx.strokeStyle = pDark;
        ctx.lineWidth = 1 * s;
        ctx.stroke();
        ctx.fillStyle = pHi;
        ctx.fillRect(-1.5 * s, -4 * s, 3 * s, 6 * s);
        ctx.restore();
      }
    }

    // 4. Head, Helmet or Cowl
    ctx.save();
    ctx.translate(0, -19.5 * s + kin.headPitch * 8 * s);

    if (isPyroOrHemo) {
      // Dark pointed pyromancer/hemomancer hood with gold trim & masked lower face
      ctx.fillStyle = "#26120b";
      ctx.beginPath();
      ctx.moveTo(0, -11.5 * s);
      ctx.quadraticCurveTo(10.5 * s, -6 * s, 9.5 * s, 6.5 * s);
      ctx.lineTo(-9.5 * s, 6.5 * s);
      ctx.quadraticCurveTo(-10.5 * s, -6 * s, 0, -11.5 * s);
      ctx.closePath();
      ctx.fill();

      // Warm skin slit visible inside hood
      ctx.fillStyle = skin.base;
      ctx.beginPath();
      ctx.ellipse(0, 0, 5.2 * s, 2.8 * s, 0, 0, Math.PI * 2);
      ctx.fill();

      // Dark face mask over nose/chin
      ctx.fillStyle = "#170b07";
      ctx.beginPath();
      ctx.roundRect(-6.5 * s, 0.5 * s, 13 * s, 6 * s, 2 * s);
      ctx.fill();

      // Gold hood rim & crown gem
      ctx.strokeStyle = "#f59e0b";
      ctx.lineWidth = 1.4 * s;
      ctx.beginPath();
      ctx.moveTo(-6.8 * s, 0.2 * s);
      ctx.quadraticCurveTo(0, -6.5 * s, 6.8 * s, 0.2 * s);
      ctx.stroke();
      ctx.fillStyle = "#fbbf24";
      ctx.beginPath();
      ctx.arc(0, -3.4 * s, 1.4 * s, 0, Math.PI * 2);
      ctx.fill();
    } else if (!isMage && !isRanger) {
      // Faceted Knight Great-Helm with Red Crest Plume & Glowing Visor Slit
      const hLight = isDragonTheme ? "#f87171" : isFrostTheme ? "#e0f2fe" : "#e2e8f0";
      const hMid = isDragonTheme ? "#991b1b" : isFrostTheme ? "#38bdf8" : "#94a3b8";
      const hDark = isDragonTheme ? "#450a0a" : isFrostTheme ? "#0284c7" : "#475569";

      // Crimson plume crest
      ctx.fillStyle = "#dc2626";
      ctx.beginPath();
      ctx.moveTo(0, -18 * s);
      ctx.lineTo(3.2 * s, -9 * s);
      ctx.lineTo(-2.5 * s, -9 * s);
      ctx.closePath();
      ctx.fill();

      // Helmet dome & faceted cheekguards
      ctx.fillStyle = hMid;
      ctx.beginPath();
      ctx.moveTo(0, -11.5 * s);
      ctx.lineTo(8.5 * s, -5.5 * s);
      ctx.lineTo(8 * s, 6.5 * s);
      ctx.lineTo(0, 9 * s);
      ctx.lineTo(-8 * s, 6.5 * s);
      ctx.lineTo(-8.5 * s, -5.5 * s);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = hLight;
      ctx.beginPath();
      ctx.moveTo(0, -11.5 * s);
      ctx.lineTo(0, 9 * s);
      ctx.lineTo(-8 * s, 6.5 * s);
      ctx.lineTo(-8.5 * s, -5.5 * s);
      ctx.closePath();
      ctx.fill();

      // Gold brow band & lower trim
      ctx.fillStyle = "#f59e0b";
      ctx.fillRect(-8.6 * s, -2.5 * s, 17.2 * s, 2 * s);
      ctx.strokeStyle = "#f59e0b";
      ctx.lineWidth = 1.5 * s;
      ctx.beginPath();
      ctx.moveTo(-7.5 * s, 5.5 * s);
      ctx.lineTo(0, 8.8 * s);
      ctx.lineTo(7.5 * s, 5.5 * s);
      ctx.stroke();

      // Dark visor slit with glowing eyes & vertical breathing grates
      ctx.fillStyle = "#0f172a";
      ctx.fillRect(-6.5 * s, -0.5 * s, 13 * s, 2.3 * s);
      ctx.fillStyle = isFrostTheme ? "#38bdf8" : "#fbbf24";
      ctx.fillRect(-4.2 * s, 0.1 * s, 2.6 * s, 1.1 * s);
      ctx.fillRect(1.6 * s, 0.1 * s, 2.6 * s, 1.1 * s);

      ctx.fillStyle = hDark;
      for (let g = -5; g <= 5; g += 2) {
        ctx.fillRect((g - 0.5) * s, 2.6 * s, 1 * s, 3 * s);
      }
    } else {
      // Smooth Faceted Ovoid Head (Mage / Ranger Game Model Style)
      const headGrad = ctx.createLinearGradient(-5 * s, -9 * s, 5 * s, 7 * s);
      if (isMage) {
        headGrad.addColorStop(0, "#ffffff");
        headGrad.addColorStop(0.55, "#e2e8f0");
        headGrad.addColorStop(1, "#94a3b8");
      } else {
        headGrad.addColorStop(0, skin.hi);
        headGrad.addColorStop(0.55, skin.base);
        headGrad.addColorStop(1, skin.shade);
      }
      ctx.fillStyle = headGrad;
      ctx.beginPath();
      ctx.ellipse(0, -1 * s, 6.2 * s, 8.2 * s, 0, 0, Math.PI * 2);
      ctx.fill();

      // Optional Capybara Hat if capybara_companion preset
      if (helmet.includes("capybara")) {
        ctx.fillStyle = "#b5703a";
        ctx.beginPath();
        ctx.ellipse(0, -7.5 * s, 7.2 * s, 4.5 * s, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#8a5530";
        ctx.beginPath();
        ctx.arc(-5 * s, -10.5 * s, 2 * s, 0, Math.PI * 2);
        ctx.arc(5 * s, -10.5 * s, 2 * s, 0, Math.PI * 2);
        ctx.fill();
      }
    }
    ctx.restore(); // Head end

    // 5. Arms & Iconic Weapons
    if (isPyroOrHemo || isMage) {
      // Left sleeve & cuff
      ctx.save();
      ctx.translate(12.5 * s, -3 * s);
      ctx.rotate(-armSwing * 0.6 + 0.18);
      if (isPyroOrHemo) {
        ctx.fillStyle = "#1c0e09";
        ctx.beginPath();
        ctx.roundRect(-4.2 * s, 0, 8.4 * s, 11 * s, 2 * s);
        ctx.fill();
        ctx.strokeStyle = "#f59e0b";
        ctx.lineWidth = 1.5 * s;
        ctx.beginPath();
        ctx.ellipse(0, 10.5 * s, 5 * s, 2.2 * s, 0, 0, Math.PI * 2);
        ctx.stroke();
        ctx.fillStyle = "#fb923c";
        ctx.beginPath();
        ctx.arc(0, 10.5 * s, 1.8 * s, 0, Math.PI * 2);
        ctx.fill();
      } else {
        ctx.fillStyle = "#171c36";
        ctx.beginPath();
        ctx.roundRect(-4 * s, 0, 8 * s, 10 * s, 2 * s);
        ctx.fill();
        ctx.fillStyle = "#7dd3fc";
        ctx.beginPath();
        ctx.arc(0, 4.5 * s, 3 * s, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#fbbf24";
        ctx.beginPath();
        ctx.arc(0, 10 * s, 2 * s, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();

      // Right hand holding the Staff vertically on screen-left (matching game studio render)
      ctx.save();
      ctx.translate(-12.5 * s, -2 * s);
      ctx.rotate(armSwing * 0.5 + kin.swingOffset * 0.45);

      const isRubyMageStaff = isMage && !weapon.includes("slime") && !weapon.includes("lightning");
      const staffTopY = -20 * s;
      const staffBotY = 30 * s;

      // Staff Shaft with metallic rings
      const shaftGrad = ctx.createLinearGradient(-2.5 * s, 0, 2.5 * s, 0);
      if (isRubyMageStaff) {
        shaftGrad.addColorStop(0, "#450a0a");
        shaftGrad.addColorStop(0.5, "#dc2626");
        shaftGrad.addColorStop(1, "#450a0a");
      } else {
        shaftGrad.addColorStop(0, "#431407");
        shaftGrad.addColorStop(0.5, "#ea580c");
        shaftGrad.addColorStop(1, "#431407");
      }
      ctx.fillStyle = shaftGrad;
      ctx.fillRect(-2.4 * s, staffTopY, 4.8 * s, staffBotY - staffTopY);

      // Ribbed grip rings along shaft
      ctx.fillStyle = isRubyMageStaff ? "#7f1d1d" : "#7c2d12";
      for (let ry = -6; ry <= 18; ry += 4) {
        ctx.fillRect(-2.8 * s, ry * s, 5.6 * s, 1.6 * s);
      }

      // Bottom Staff Spike Tip
      ctx.fillStyle = isRubyMageStaff ? "#ef4444" : "#f97316";
      ctx.beginPath();
      ctx.moveTo(-2.6 * s, staffBotY);
      ctx.lineTo(0, staffBotY + 6.5 * s);
      ctx.lineTo(2.6 * s, staffBotY);
      ctx.closePath();
      ctx.fill();

      // Curved Crescent Wings cradling the Staff Orb
      ctx.fillStyle = isRubyMageStaff ? "#ef4444" : "#fb923c";
      for (const side of [-1, 1]) {
        ctx.beginPath();
        ctx.moveTo(0, staffTopY + 5 * s);
        ctx.quadraticCurveTo(side * 13 * s, staffTopY + 2 * s, side * 12 * s, staffTopY - 9 * s);
        ctx.quadraticCurveTo(side * 7 * s, staffTopY - 2 * s, 0, staffTopY + 1 * s);
        ctx.closePath();
        ctx.fill();
      }

      // Large 3D Shaded Staff Orb
      const orbY = staffTopY - 3.5 * s;
      const orbR = 9.2 * s;
      const orbGrad = ctx.createRadialGradient(-3 * s, orbY - 3 * s, 1 * s, 0, orbY, orbR);
      if (isRubyMageStaff) {
        orbGrad.addColorStop(0, "#fecdd3");
        orbGrad.addColorStop(0.3, "#e11d48");
        orbGrad.addColorStop(0.75, "#9f1239");
        orbGrad.addColorStop(1, "#4c0519");
      } else {
        orbGrad.addColorStop(0, "#fef9c3");
        orbGrad.addColorStop(0.3, "#fb923c");
        orbGrad.addColorStop(0.75, "#dc2626");
        orbGrad.addColorStop(1, "#7c2d12");
      }
      ctx.fillStyle = orbGrad;
      ctx.beginPath();
      ctx.arc(0, orbY, orbR, 0, Math.PI * 2);
      ctx.fill();

      // Orbiting satellite beads
      const beadColor = isRubyMageStaff ? "#fb7185" : "#fdba74";
      ctx.fillStyle = beadColor;
      ctx.beginPath();
      ctx.arc(-12.5 * s, orbY - 1 * s, 2.1 * s, 0, Math.PI * 2);
      ctx.arc(4 * s, orbY + 6 * s, 2.2 * s, 0, Math.PI * 2);
      ctx.fill();

      // Signature 4-Pointed Star Glints (exactly like the game renders!)
      const pulse = 0.92 + Math.sin(now * 0.006) * 0.14 + (this.isAttacking ? 0.35 : 0);
      if (isRubyMageStaff) {
        drawStarGlint(ctx, 7.5 * s, orbY - 8.5 * s, 8.2 * s, "#ffffff", "rgba(255,255,255,0.55)", pulse);
        drawStarGlint(ctx, 0, staffBotY + 5.5 * s, 6.8 * s, "#ffffff", "rgba(255,255,255,0.5)", pulse);
      } else {
        drawStarGlint(ctx, -1.5 * s, orbY - 8.5 * s, 9.2 * s, "#ffffff", "rgba(254,215,170,0.65)", pulse);
      }
      ctx.restore();
    } else if (isRanger) {
      // Prismatic Rainbow Bow / Crossbow held across the front with glowing arrow & feather pennants
      ctx.save();
      ctx.translate(0, 4 * s);
      ctx.rotate(-0.18 + kin.swingOffset * 0.25);

      // Rainbow curved bow wings & pennants
      const bowColors = ["#ef4444", "#f59e0b", "#eab308", "#22c55e", "#38bdf8", "#a855f7"];
      for (const side of [-1, 1]) {
        // Hanging rainbow feather tags under each wing
        for (let f = 0; f < 3; f++) {
          ctx.save();
          ctx.translate(side * (9 + f * 5.2) * s, (2 + f * 1.6) * s);
          ctx.rotate(side * 0.28);
          ctx.fillStyle = "#ffffff";
          ctx.beginPath();
          ctx.roundRect(-2.4 * s, 0, 4.8 * s, 7.5 * s, 1.2 * s);
          ctx.fill();
          ctx.strokeStyle = bowColors[(f * 2) % bowColors.length];
          ctx.lineWidth = 1.1 * s;
          ctx.strokeRect(-1.6 * s, 1 * s, 3.2 * s, 5.2 * s);
          ctx.restore();
        }

        // Multi-band rainbow arc limb
        for (let b = 0; b < 3; b++) {
          ctx.strokeStyle = bowColors[b * 2];
          ctx.lineWidth = 1.6 * s;
          ctx.beginPath();
          ctx.moveTo(0, (-2 + b * 1.4) * s);
          ctx.quadraticCurveTo(side * 14 * s, (-5 + b * 1.4) * s, side * 26 * s, (2 + b * 1.2) * s);
          ctx.stroke();
        }

        // Glowing white-cyan upper bow limb bar
        ctx.strokeStyle = "#e0f2fe";
        ctx.lineWidth = 2.6 * s;
        ctx.beginPath();
        ctx.moveTo(0, -3.5 * s);
        ctx.lineTo(side * 24 * s, 1.5 * s);
        ctx.stroke();
      }

      // Center Gold Mount & Glowing White Pearl Core
      ctx.fillStyle = "#f59e0b";
      ctx.beginPath();
      ctx.roundRect(-6.5 * s, -6 * s, 13 * s, 8 * s, 2.5 * s);
      ctx.fill();
      ctx.fillStyle = "#ffffff";
      ctx.strokeStyle = "#1e293b";
      ctx.lineWidth = 1.4 * s;
      ctx.beginPath();
      ctx.arc(0, -4.5 * s, 3.6 * s, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      // Green/Gold Fletching at top of arrow
      ctx.fillStyle = "#22c55e";
      ctx.beginPath();
      ctx.moveTo(0, -8 * s);
      ctx.lineTo(-4 * s, -14 * s);
      ctx.lineTo(0, -11.5 * s);
      ctx.lineTo(4 * s, -14 * s);
      ctx.closePath();
      ctx.fill();

      // Prismatic Arrow Shaft & Broadhead pointing down-forward
      const drawPull = this.isAttacking ? -kin.progress * 4 * s : 0;
      ctx.save();
      ctx.translate(0, drawPull);
      const shaftGrad = ctx.createLinearGradient(-2 * s, 0, 2 * s, 24 * s);
      shaftGrad.addColorStop(0, "#fde047");
      shaftGrad.addColorStop(0.5, "#38bdf8");
      shaftGrad.addColorStop(1, "#ec4899");
      ctx.fillStyle = shaftGrad;
      ctx.fillRect(-1.8 * s, -2 * s, 3.6 * s, 23 * s);

      // Crystal Arrowhead with glowing pink/white core
      ctx.fillStyle = "#ffffff";
      ctx.beginPath();
      ctx.moveTo(0, 31 * s);
      ctx.lineTo(-6.5 * s, 18 * s);
      ctx.lineTo(0, 20.5 * s);
      ctx.lineTo(6.5 * s, 18 * s);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 1.2 * s;
      ctx.stroke();

      const tipGlow = ctx.createRadialGradient(0, 23 * s, 0.5 * s, 0, 23 * s, 5 * s);
      tipGlow.addColorStop(0, "#ffffff");
      tipGlow.addColorStop(0.45, "#f43f5e");
      tipGlow.addColorStop(1, "rgba(244,63,94,0)");
      ctx.fillStyle = tipGlow;
      ctx.beginPath();
      ctx.arc(0, 23 * s, 4.8 * s, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();

      ctx.restore();
    } else {
      // Warrior / Paladin: Armored Gauntlets + Diagonal Royal Greatsword with Ruby Jewel
      ctx.save();
      ctx.translate(-7 * s, -1 * s);
      // Diagonal greatsword angle (bottom-left hilt to top-right tip, matching Image 2)
      const baseSwordAngle = 0.88 + kin.swingOffset * 0.55;
      ctx.rotate(baseSwordAngle);

      const bladeLight = isDragonTheme ? "#fecaca" : isFrostTheme ? "#ffffff" : "#ffffff";
      const bladeMid = isDragonTheme ? "#ef4444" : isFrostTheme ? "#7dd3fc" : "#cbd5e1";
      const bladeDark = isDragonTheme ? "#7f1d1d" : isFrostTheme ? "#0284c7" : "#64748b";

      // Wide Faceted Greatsword Blade extending toward upper-right (negative Y in rotated space)
      ctx.fillStyle = bladeMid;
      ctx.beginPath();
      ctx.moveTo(-5.2 * s, -2 * s);
      ctx.lineTo(-4.8 * s, -38 * s);
      ctx.lineTo(0, -45 * s);
      ctx.lineTo(4.8 * s, -38 * s);
      ctx.lineTo(5.2 * s, -2 * s);
      ctx.closePath();
      ctx.fill();

      // Bright top-edge facet
      ctx.fillStyle = bladeLight;
      ctx.beginPath();
      ctx.moveTo(-5.2 * s, -2 * s);
      ctx.lineTo(-4.8 * s, -38 * s);
      ctx.lineTo(0, -45 * s);
      ctx.lineTo(0, -2 * s);
      ctx.closePath();
      ctx.fill();

      // Dark fuller groove & notches along center
      ctx.fillStyle = "#1e293b";
      for (let f = 0; f < 5; f++) {
        ctx.fillRect(-1.1 * s, (-10 - f * 5.2) * s, 2.2 * s, 3.4 * s);
      }
      ctx.strokeStyle = bladeDark;
      ctx.lineWidth = 1 * s;
      ctx.strokeRect(-5 * s, -37 * s, 10 * s, 35 * s);

      // Ornate Gold Crossguard with Spherical Finials
      ctx.fillStyle = "#d97706";
      ctx.beginPath();
      ctx.moveTo(-13 * s, -3.5 * s);
      ctx.lineTo(13 * s, -3.5 * s);
      ctx.lineTo(11 * s, 1.5 * s);
      ctx.lineTo(-11 * s, 1.5 * s);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = "#fbbf24";
      ctx.fillRect(-11 * s, -2.8 * s, 22 * s, 2 * s);

      // Gold spherical crossguard tips
      for (const side of [-1, 1]) {
        const gBall = ctx.createRadialGradient(side * 13 * s, -1.5 * s, 0.5 * s, side * 13.5 * s, -1 * s, 3.8 * s);
        gBall.addColorStop(0, "#fef08a");
        gBall.addColorStop(0.55, "#f59e0b");
        gBall.addColorStop(1, "#92400e");
        ctx.fillStyle = gBall;
        ctx.beginPath();
        ctx.arc(side * 13.5 * s, -1 * s, 3.5 * s, 0, Math.PI * 2);
        ctx.fill();
      }

      // Ribbed Gold Grip & Pommel with Ruby Gems
      ctx.fillStyle = "#b45309";
      ctx.fillRect(-2.4 * s, 1.5 * s, 4.8 * s, 11.5 * s);
      ctx.fillStyle = "#fbbf24";
      for (let g = 0; g < 3; g++) {
        ctx.fillRect(-2.6 * s, (3 + g * 3.2) * s, 5.2 * s, 1.5 * s);
      }
      // Pommel sphere
      const pBall = ctx.createRadialGradient(-0.8 * s, 14.5 * s, 0.5 * s, 0, 15 * s, 3.8 * s);
      pBall.addColorStop(0, "#fef08a");
      pBall.addColorStop(0.55, "#f59e0b");
      pBall.addColorStop(1, "#78350f");
      ctx.fillStyle = pBall;
      ctx.beginPath();
      ctx.arc(0, 15 * s, 3.5 * s, 0, Math.PI * 2);
      ctx.fill();

      // Large Center Crimson Ruby Cabochon in Crossguard
      const rubyGrad = ctx.createRadialGradient(-1.2 * s, -2.2 * s, 0.5 * s, 0, -1 * s, 4.5 * s);
      rubyGrad.addColorStop(0, "#fecdd3");
      rubyGrad.addColorStop(0.35, "#e11d48");
      rubyGrad.addColorStop(0.8, "#9f1239");
      rubyGrad.addColorStop(1, "#4c0519");
      ctx.fillStyle = rubyGrad;
      ctx.beginPath();
      ctx.arc(0, -1 * s, 4.2 * s, 0, Math.PI * 2);
      ctx.fill();

      ctx.restore();
    }

    ctx.restore(); // Torso end

    // 6. Dynamic Attack Slash / Cast Arc
    if (this.isAttacking && kin.progress > 0.08 && kin.progress < 0.96) {
      ctx.save();
      const alpha = Math.max(0, Math.min(1, 1 - Math.abs(kin.progress - 0.55) * 1.6));
      const arcColor = isPyroOrHemo ? `rgba(251, 146, 60, ${alpha})`
        : isMage ? `rgba(244, 63, 94, ${alpha})`
        : isRanger ? `rgba(56, 189, 248, ${alpha})`
        : `rgba(251, 191, 36, ${alpha})`;
      ctx.strokeStyle = arcColor;
      ctx.lineWidth = 3.8 * s;
      ctx.beginPath();
      ctx.arc(0, -4 * s, 28 * s, -Math.PI * 0.45, Math.PI * 0.45);
      ctx.stroke();
      ctx.restore();
    }

    ctx.restore(); // Root Transform
  }
}

// ---------------------------------------------------------------------------
// 5. READY-TO-USE INTERACTIVE CANVAS MOUNT HELPER
// ---------------------------------------------------------------------------
/**
 * Convenience helper that binds a character to any <canvas> element with
 * keyboard navigation (WASD / Arrows to walk, Space to attack combo, Shift to roll).
 * @param {HTMLCanvasElement} canvas
 * @param {string} [presetId]
 */
export function mountCharacterCanvas(canvas, presetId = "active_setup") {
  if (!canvas || !canvas.getContext) {
    throw new Error("Invalid canvas element provided to mountCharacterCanvas.");
  }
  const ctx = canvas.getContext("2d");
  const character = new CharacterController(CHARACTER_PRESETS.find(p => p.id === presetId) || CHARACTER_PRESETS[0]);

  const keys = { w: false, a: false, s: false, d: false };

  window.addEventListener("keydown", (e) => {
    if (e.code === "Space") {
      e.preventDefault();
      character.triggerAttack();
    } else if (e.code === "ShiftLeft" || e.code === "KeyR") {
      character.triggerRoll();
    } else if (e.code === "KeyW" || e.code === "ArrowUp") keys.w = true;
    else if (e.code === "KeyA" || e.code === "ArrowLeft") keys.a = true;
    else if (e.code === "KeyS" || e.code === "ArrowDown") keys.s = true;
    else if (e.code === "KeyD" || e.code === "ArrowRight") keys.d = true;
  });

  window.addEventListener("keyup", (e) => {
    if (e.code === "KeyW" || e.code === "ArrowUp") keys.w = false;
    else if (e.code === "KeyA" || e.code === "ArrowLeft") keys.a = false;
    else if (e.code === "KeyS" || e.code === "ArrowDown") keys.s = false;
    else if (e.code === "KeyD" || e.code === "ArrowRight") keys.d = false;
  });

  let lastTime = performance.now();

  function loop(now) {
    const dt = (now - lastTime) / 1000;
    lastTime = now;

    let vx = 0;
    let vy = 0;
    if (keys.w) vy -= 1;
    if (keys.s) vy += 1;
    if (keys.a) vx -= 1;
    if (keys.d) vx += 1;

    const isMoving = vx !== 0 || vy !== 0;
    character.setMoving(isMoving);
    if (isMoving) {
      character.setFacingAngle(Math.atan2(vy, vx));
    }

    character.update(dt);

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    character.draw(ctx, canvas.width / 2, canvas.height / 2, 2.5);

    requestAnimationFrame(loop);
  }

  requestAnimationFrame(loop);
  return character;
}

if (typeof window !== "undefined") {
  window.CharacterRenderer = {
    CHARACTER_PRESETS,
    CharacterController,
    getWeaponCategory,
    isTwoHandedWeapon,
    getPlayerAttackDuration,
    getDefaultWeaponWristAngle,
    getAttackKinematics,
    mountCharacterCanvas
  };
}
